// JOB 1 — inadimplência: dias de atraso, faixas 1-30/31-60/61-90/90+ e rascunho de mensagem.
const OBRIGATORIAS = ['Cliente', 'Vencimento'];
const hoje = new Date();
hoje.setHours(0, 0, 0, 0);

function parseData(s) {
  if (s == null || s === '') return null;
  s = String(s).trim();
  let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  return null;
}

function parseValor(v) {
  if (typeof v === 'number') return v;
  if (v == null) return 0;
  let s = String(v).replace(/[^0-9.,-]/g, '');
  if (s.includes('.') && s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) s = s.replace(',', '.');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
}

const linhas = $input.all().map((i) => i.json);
if (linhas.length) {
  const faltando = OBRIGATORIAS.filter((c) => !(c in linhas[0]));
  if (faltando.length) {
    throw new Error(`Aba Relatorio_Inadimplencia sem as colunas: ${faltando.join(', ')}. Confira o cabeçalho (ver planilhas-modelo.md).`);
  }
}

const out = [];
for (const l of linhas) {
  if (!l.Cliente) continue;
  const venc = parseData(l.Vencimento);
  if (!venc) continue;
  const diasAtraso = Math.floor((hoje - venc) / 86400000);
  if (diasAtraso <= 0) continue; // ainda não venceu
  const faixa = diasAtraso <= 30 ? '1-30' : diasAtraso <= 60 ? '31-60' : diasAtraso <= 90 ? '61-90' : '90+';
  const valor = parseValor(l.Valor);
  out.push({
    json: {
      Tipo: 'inadimplencia',
      Cliente: String(l.Cliente).trim(),
      Telefone: String(l.Telefone || '').trim(),
      Placa: String(l.Placa || '').trim(),
      Contrato: String(l.Contrato || '').trim(),
      Valor: valor,
      Vencimento: String(l.Vencimento).trim(),
      DiasAtraso: diasAtraso,
      Faixa: faixa,
      Detalhe: `${diasAtraso}d de atraso · R$ ${valor.toFixed(2)}`,
      Mensagem: `Olá ${String(l.Cliente).trim().split(' ')[0]}, tudo bem? Identificamos uma parcela do contrato ${l.Contrato || ''} (placa ${l.Placa || ''}) em aberto desde ${String(l.Vencimento).trim()}, no valor de R$ ${valor.toFixed(2)}. Podemos te ajudar a regularizar? Qualquer dúvida estamos à disposição.`,
    },
  });
}
return out;

// JOB 2 — renovações: dias até o fim de vigência, janelas ≤30 / 31-60 / 61-90.
const OBRIGATORIAS = ['Cliente', 'FimVigencia'];
const hoje = new Date();
hoje.setHours(0, 0, 0, 0);

function parseData(s) {
  if (s == null || s === '') return null;
  s = String(s).trim();
  let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  return null;
}

const linhas = $input.all().map((i) => i.json);
if (linhas.length) {
  const faltando = OBRIGATORIAS.filter((c) => !(c in linhas[0]));
  if (faltando.length) {
    throw new Error(`Aba Relatorio_Renovacoes sem as colunas: ${faltando.join(', ')}. Confira o cabeçalho (ver planilhas-modelo.md).`);
  }
}

const out = [];
for (const l of linhas) {
  if (!l.Cliente) continue;
  const fim = parseData(l.FimVigencia);
  if (!fim) continue;
  const dias = Math.floor((fim - hoje) / 86400000);
  if (dias > 90) continue; // fora do radar do piloto
  const janela = dias < 0 ? 'vencido' : dias <= 30 ? '<=30' : dias <= 60 ? '31-60' : '61-90';
  const primeiroNome = String(l.Cliente).trim().split(' ')[0];
  out.push({
    json: {
      Tipo: 'renovacao',
      Cliente: String(l.Cliente).trim(),
      Telefone: String(l.Telefone || '').trim(),
      Placa: String(l.Placa || '').trim(),
      Contrato: String(l.Contrato || '').trim(),
      FimVigencia: String(l.FimVigencia).trim(),
      DiasParaVencer: dias,
      Janela: janela,
      Detalhe: dias < 0 ? `vencido há ${-dias}d` : `vence em ${dias}d`,
      Mensagem: dias < 0
        ? `Olá ${primeiroNome}! Seu contrato ${l.Contrato || ''} (placa ${l.Placa || ''}) venceu em ${String(l.FimVigencia).trim()}. Vamos reativar sua proteção?`
        : `Olá ${primeiroNome}! Seu contrato ${l.Contrato || ''} (placa ${l.Placa || ''}) vence em ${dias} dias, em ${String(l.FimVigencia).trim()}. Vamos garantir a renovação e manter seu veículo protegido?`,
    },
  });
}
return out;

// Consolida os dois jobs numa linha de resumo diário + texto do Telegram.
const itens = $input.all().map((i) => i.json);
const inad = itens.filter((x) => x.Tipo === 'inadimplencia');
const ren = itens.filter((x) => x.Tipo === 'renovacao');

const porFaixa = (f) => inad.filter((x) => x.Faixa === f).length;
const porJanela = (j) => ren.filter((x) => x.Janela === j).length;
const valorTotal = inad.reduce((s, x) => s + (x.Valor || 0), 0);
const maisAntigo = inad.reduce((m, x) => Math.max(m, x.DiasAtraso || 0), 0);

const agora = new Date();
const data = `${String(agora.getDate()).padStart(2, '0')}/${String(agora.getMonth() + 1).padStart(2, '0')}/${agora.getFullYear()}`;

const resumo = {
  Data: data,
  InadimplentesTotal: inad.length,
  ValorTotal: Number(valorTotal.toFixed(2)),
  Faixa1a30: porFaixa('1-30'),
  Faixa31a60: porFaixa('31-60'),
  Faixa61a90: porFaixa('61-90'),
  Faixa90mais: porFaixa('90+'),
  MaisAntigoDias: maisAntigo,
  RenovacoesTotal: ren.length,
  Renov30: porJanela('<=30') + porJanela('vencido'),
  Renov60: porJanela('31-60'),
  Renov90: porJanela('61-90'),
};

const linhasTelegram = [
  `📋 *Resumo operacional — ${data}*`,
  '',
  `💰 *Inadimplência:* ${inad.length} casos · R$ ${valorTotal.toFixed(2)}`,
  `   1-30: ${resumo.Faixa1a30} · 31-60: ${resumo.Faixa31a60} · 61-90: ${resumo.Faixa61a90} · 90+: ${resumo.Faixa90mais}` + (maisAntigo ? ` (mais antigo: ${maisAntigo}d)` : ''),
  '',
  `🔄 *Renovações (≤90d):* ${ren.length}`,
  `   ≤30: ${resumo.Renov30} · 31-60: ${resumo.Renov60} · 61-90: ${resumo.Renov90}`,
  '',
  `✉️ ${itens.length} rascunhos aguardando revisão na aba Message Queue.`,
  '_Nada foi enviado a clientes. Robô read-only._',
];

resumo.TelegramText = linhasTelegram.join('\n');
return [{ json: resumo }];

// JOB 3 — fila de rascunhos: um por caso, status pending. Humano revisa e envia manualmente.
const data = $('Consolidar Resumo').first().json.Data;
const casos = $('Merge').all().map((i) => i.json);

return casos.map((x) => ({
  json: {
    Data: data,
    Tipo: x.Tipo,
    Cliente: x.Cliente,
    Telefone: x.Telefone,
    Contrato: x.Contrato,
    Placa: x.Placa,
    Detalhe: x.Detalhe,
    Mensagem: x.Mensagem,
    Status: 'pending',
    AprovadoPor: '',
    Enviado: '',
  },
}));
